{
  "name": "Primary Home Care (Community Care)",
  "eligibility": {
    "age": 21,
    "income_limits": {
      "summary": "This program is for adults age 21+ who are Medicaid eligible in the community, or who qualify under Section 1929(b)(2)(B) of the Social Security Act. The most specific dollar figures surfaced for this program are $2,829/month for a single person and $5,658/month for a married couple in the rights-and-responsibilities notice; a separate Texas rule for community care services also shows a community-care income ceiling of $1,302/month and a resource limit of $5,000, but that appears to be a broader community-care rule and should be reconciled against the specific PHC/CAS eligibility notice before relying on it.",
      "table": [
        {
          "household": "Single",
          "monthly_income_limit": "$2,829",
          "source_context": "PHC/CAS rights and responsibilities notice"
        },
        {
          "household": "Married",
          "monthly_income_limit": "$5,658",
          "source_context": "PHC/CAS rights and responsibilities notice"
        }
      ]
    },
    "asset_limits": {
      "summary": "The PHC/CAS notice says resources must not exceed $2,000 for a single person and $3,000 for a married person. A separate Texas community-care rule snippet shows a $5,000 resource limit for community care services generally, so families should verify which resource standard the local HHSC/CCSE office is using for the specific pathway being screened.",
      "limits": [
        {
          "household": "Single",
          "resource_limit": "$2,000"
        },
        {
          "household": "Married",
          "resource_limit": "$3,000"
        }
      ],
      "what_counts": "The surfaced sources do not give a full asset-counting/exempt-asset schedule for PHC specifically.",
      "what_is_exempt": "Not specified in the surfaced sources; treat this as needing local HHSC confirmation."
    },
    "other_requirements": [
      "Must have a practitioner's statement of medical need.",
      "Must have a functional impairment score of at least 24.",
      "Must need help with at least one personal care task such as bathing, feeding, meal preparation, toileting, transferring, or medication reminders.",
      "Must need help with activities of daily living.",
      "Must need at least 6 hours of service per week, unless an exception applies.",
      "If needing fewer than 6 hours per week, the person may still qualify if the service is needed for caregiver respite, if they live with someone who also receives certain attendant-care services, if they receive one of the listed qualifying services/benefits, or if other rule-based exceptions are met.",
      "Must reside in a community setting, not in a hospital, nursing facility, ICF, assisted living facility, foster care setting, jail/prison, state school, or state hospital.",
      "PHC is not available to individuals under 21 with full Medicaid benefits; those cases are routed through CAS screening instead."
    ]
  },
  "benefits": {
    "type": "service",
    "value": "Non-technical, non-skilled, in-home attendant/personal assistance services for help with personal care tasks and activities of daily living. The program is delivered as attendant support rather than cash. A client with priority status may receive no more than 42 hours per week; a client without priority status may receive no more than 50 hours per week.",
    "varies_by": "priority_tier"
  },
  "application": {
    "methods": [
      "Contact the local HHSC Community Care for the Aged and Disabled (CCSE) office / local area agency for intake and screening.",
      "Use the Texas HHSC community-care handbook and local office referrals to start screening.",
      "For provider-side participation information, HHSC lists the PHC provider page at the official HHSC provider site."
    ],
    "processing_time": "Not specified in the surfaced official materials. The key operational reality is that eligibility depends on CCSE screening, and service access can be immediate or delayed depending on local provider capacity and priority status.",
    "waitlist": "A formal statewide PHC waitlist was not identified in the surfaced sources; practical access may still be delayed locally because of provider availability and priority handling.",
    "forms": [
      "Attachment 2307-A, Family Care, Community Attendant Services and Primary Home Care Rights and Responsibilities",
      "Practitioner's statement of medical need (exact form title not surfaced in the retrieved results)"
    ],
    "documents": [
      "Proof of Medicaid eligibility, if already enrolled",
      "Income documentation",
      "Resource/asset information",
      "Practitioner's statement of medical need",
      "Information about help needed with personal care tasks and ADLs",
      "Identification and household information",
      "Any current service or benefit information relevant to the 6-hour-per-week exception screening"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available statewide in Texas for eligible adults, but the applicant must live in a community setting and not in an excluded institutional or correctional setting.",
    "regional_variations": "The core eligibility rules are statewide, but actual access can vary by local CCSE office, local provider capacity, and whether the person is screened as priority status. The surfaced materials do not provide a county-by-county table of differences.",
    "offices_or_providers": [
      "Local HHSC CCSE offices",
      "HHSC-contracted PHC providers"
    ]
  },
  "official_source": "https://fhb.hhs.texas.gov/handbooks/community-care-services-eligibility-handbook/4600-primary-home-care-community-attendant-services",
  "gotchas": [
    "PHC is not a general home-care benefit for everyone; it is tied to Medicaid/community-care eligibility plus a medical and functional need test.",
    "The functional score threshold matters: a practitioner note alone is not enough.",
    "The six-hours-per-week rule is a common trap; people with lower assessed need may still qualify only through specific exceptions.",
    "Age 21 is a key cutoff: people under 21 with full Medicaid benefits are not routed through PHC the same way.",
    "Priority status affects the maximum weekly hours available.",
    "Two different dollar-limit sets surfaced in the available materials, so families should confirm the exact income/resource test with the local HHSC office before assuming they qualify or do not qualify."
  ],
  "data_shape_notes": "This program is not a simple income-only benefit. It is a Medicaid-linked, medically justified attendant-care service with both financial screening and a functional-assessment threshold, plus a weekly-hours cap that can vary by priority status."
}
